    User = apps.get_model("auth", "User")

    taken = set()

    def claim(member, user):
        if user.pk in taken:
            return False
        member.account_id = user.pk
        member.save(update_fields=["account"])
        taken.add(user.pk)
        return True

    staff = list(User.objects.filter(is_staff=True))
    members = list(TeamMember.objects.all())

    for member in members:
        if not member.email:
            continue
        hit = [u for u in staff if u.email and u.email.lower() == member.email.lower()]
        if len(hit) == 1:
            claim(member, hit[0])

    for member in members:
        if member.account_id:
            continue
        name = member.name.strip().lower()
        hit = [
            u for u in staff
            if u.pk not in taken
            and f"{u.first_name} {u.last_name}".strip().lower() == name
        ]
        if len(hit) == 1:
            claim(member, hit[0])


